public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();

    // Base case: if the input array has only one element,
    // return a list containing only one list with that element
    if (nums.length == 1) {
        permutations.add(new ArrayList<>(Arrays.asList(nums[0])));
        return permutations;
    }

    // Recursive case: for each element in the input array,
    // generate all permutations of the remaining elements
    // and put the current element in each of those permutations
    for (int i = 0; i < nums.length; i++) {
        int current = nums[i];
        int[] remaining = Arrays.copyOfRange(nums, 0, nums.length - 1);
        List<List<Integer>> remainingPermutations = permute(remaining);
        for (List<Integer> permutation : remainingPermutations) {
            permutation.add(current);
        }
        permutations.addAll(remainingPermutations);
    }

    return permutations;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 0) {
        return result;
    }

    permute(nums, 0, result);

    return result;
}

private void permute(int[] nums, int start, List<List<Integer>> result) {
    if (start == nums.length) {
        List<Integer> permutation = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            permutation.add(nums[i]);
        }
        result.add(permutation);
        return;
    }

    for (int i = start; i < nums.length; i++) {
        swap(nums, start, i);
        permute(nums, start + 1, result);
        swap(nums, start, i);
    }
}

private void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    boolean[] used = new boolean[nums.length];
    Arrays.fill(used, false);
    permute(result, new ArrayList<>(), nums, used);
    return result;
}

private void permute(List<List<Integer>> result, List<Integer> current, int[] nums, boolean[] used) {
    if (current.size() == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }

    for (int i = 0; i < nums.length; i++) {
        if (!used[i]) {
            used[i] = true;
            current.add(nums[i]);
            permute(result, current, nums, used);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 0) {
        return result;
    } else if (nums.length == 1) {
        result.add(Arrays.asList(nums[0]));
        return result;
    } else {
        for (int i = 0; i < nums.length; i++) {
            int[] remaining = Arrays.copyOfRange(nums, i + 1, nums.length);
            List<List<Integer>> permutations = permute(remaining);
            for (List<Integer> permutation : permutations) {
                permutation.add(i, nums[i]);
                result.add(permutation);
            }
        }
    }
    return result;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    backtrack(nums, 0, result);
    return result;
}

private void backtrack(int[] nums, int start, List<List<Integer>> result) {
    if (start == nums.length) {
        result.add(Arrays.stream(nums).boxed().collect(Collectors.toList()));
        return;
    }
    for (int i = start; i < nums.length; i++) {
        swap(nums, start, i);
        backtrack(nums, start + 1, result);
        swap(nums, start, i);
    }
}

private void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
}

