public int findLargestSubstring(List<String> strings) {
    // If the list of strings is empty, return -1
    if (strings.isEmpty()) {
        return -1;
    }

    // Initialize the largest string to be the first string in the list
    String largestString = strings.get(0);

    // Iterate through the rest of the strings in the list, comparing their lengths to the current largest string
    for (int i = 1; i < strings.size(); i++) {
        String currentString = strings.get(i);
        if (currentString.length() > largestString.length()) {
            largestString = currentString;
        }
    }

    // Iterate through the list of strings again, checking if the largest string or its inverse is present
    for (String currentString : strings) {
        if (currentString.contains(largestString) || currentString.contains(largestString.replaceAll(".", ""))) {
            return largestString.length();
        }
    }

    // If the largest string was not found in any of the strings, return -1
    return -1;
}

