public static int countOilDeposits(char[][] grid) {
    int numOilDeposits = 0;
    int R = grid.length, C = grid[0].length; // number of rows and columns in the grid

    for (int i = 0; i < R; i++) {
        for (int j = 0; j < C; j++) {
            // check if the current cell is an oil deposit
            if (grid[i][j] == '@') {
                // traverse the grid in all 4 directions to find the boundaries of the oil deposit
                int startX = j, startY = i; // starting x and y coordinates
                int endX = j, endY = i; // ending x and y coordinates

                // traverse left
                while (startX > 0 && grid[startY][startX - 1] == '@') startX--;

                // traverse right
                while (endX < C - 1 && grid[endY][endX + 1] == '@') endX++;

                // traverse up
                while (startY > 0 && grid[startY - 1][startX] == '@') startY--;

                // traverse down
                while (endY < R - 1 && grid[endY + 1][endX] == '@') endY++;

                // check if the boundary of the oil deposit is a square
                if (startX == endX && startY == endY) {
                    numOilDeposits++; // increment the number of oil deposits
                }
            }
        }
    }

    return numOilDeposits;
}

