        for (int[] path : paths) {
            if (path[0] == x && path[1] == y) {
                int nextX = path[2], nextY = path[3];
                if (nextX == endX && nextY == endY) {
                    return "can be travelled";
                }
                if (!visited[nextX][nextY]) {
                    visited[nextX][nextY] = true;
                    queue.add(new int[]{nextX, nextY});
                }
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n < 1 || start.length != 2 || end.length != 2 || paths.length == 0) {
      return "cannot be travelled";
    }

    int startX = start[0];
    int startY = start[1];
    int endX = end[0];
    int endY = end[1];

    if (startX == endX && startY == endY) {
      return "can be travelled";
    }

    // Loop through each path and check if there is a path between the starting and ending n-tersections
    for (int i = 0; i < paths.length; i++) {
      int[] path = paths[i];
      if (path.length == 2) {
        int x = path[0];
        int y = path[1];
        if (x == startX && y == startY) {
          return "can be travelled";
        }
      }
    }

    return "cannot be travelled";
  }

