int maxIndex = (int)Math.round(0.95*arrayLength);

// Copy array and sort it
int[] arrCopy = arr.clone();
Arrays.sort(arrCopy);

// Get sum of all elements
double sum = 0;
for (int i=minIndex ; i < maxIndex ; i++) {
    sum += arrCopy[i];
}

