public double trimMean(int[] arr) {
    int n = arr.length;
    int lowerTrimIndex = (int) (0.05 * n);
    int upperTrimIndex = (int) (0.95 * n);
    Arrays.sort(arr);
    int sum = 0;
    for (int i = lowerTrimIndex; i <= upperTrimIndex; i++) {
        sum += arr[i];
    }
    return (double) sum / (upperTrimIndex - lowerTrimIndex + 1);
}

public double trimMean(int[] arr) {
    int n = arr.length;
    int n10 = (n - 1) / 10;
    int[] newArr = new int[n - 2 * n10];
    System.arraycopy(arr, n10, newArr, 0, n - n10);
    Arrays.sort(newArr);
    double sum = 0.0;
    for (int i = n10; i < newArr.length - n10; i++) {
        sum += newArr[i];
    }
    return sum / (newArr.length - 2 * n10);
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Input array cannot be null or empty");
    }

    // Sort the array in ascending order
    Arrays.sort(arr);

    // Find the 5% of the lowest elements to be removed
    int numToRemove = (int) Math.ceil(arr.length * 0.05);

    // Find the 5% of the highest elements to be removed
    int numToRemove = (int) Math.ceil(arr.length * 0.05);

    // Create new arrays with the elements to be removed removed
    int[] low = Arrays.copyOfRange(arr, 0, numToRemove);
    int[] high = Arrays.copyOfRange(arr, arr.length - numToRemove, arr.length);

    // Calculate the mean of the remaining elements
    double mean = Arrays.stream(arr).filter(x -> !Arrays.asList(low).contains(x) && !Arrays.asList(high).contains(x)).mapToDouble(x -> x).average().orElseThrow();

    return mean;
}

public double trimMean(int[] arr) {
    int n = arr.length;
    if (n <= 20) {
        // If the array has less than 20 elements, return the mean of all elements
        double sum = 0;
        for (int i = 0; i < n; i++) {
            sum += arr[i];
        }
        return sum / n;
    }

    // Else, calculate the mean of the trimmed array
    int[] trimmedArr = new int[n - 10];
    for (int i = 5; i < n - 5; i++) {
        trimmedArr[i - 5] = arr[i];
    }

    double sum = 0;
    for (int i = 0; i < trimmedArr.length; i++) {
        sum += trimmedArr[i];
    }
    return sum / (trimmedArr.length + 1);
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length == 0) {
        return false;
    }
    if (k <= 0) {
        throw new IllegalArgumentException("Invalid value for k");
    }
    if (arr.length % 2 != 0) {
        return false;
    }
    Arrays.sort(arr);
    int n = arr.length / 2;
    for (int i = 0, j = n - 1; i < n; i++, j--) {
        if ((arr[i] + arr[j]) % k != 0) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    HashMap<Integer, Integer> map = new HashMap<>();
    for (int i = 0; i < arr.length; i++) {
        int remainder = arr[i] % k;
        if (map.containsKey(remainder)) {
            map.put(remainder, map.get(remainder) + 1);
        } else {
            map.put(remainder, 1);
        }
    }

    for (int remainder : map.keySet()) {
        if (map.get(remainder) % 2 == 1) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    // Check if the array is not null or empty and the divisor is positive
    if (arr == null || arr.length == 0 || k <= 0) {
        return false;
    }

    // Initialize a hash map to store the counts of numbers modulo k
    Map<Integer, Integer> map = new HashMap<>();

    // Iterate through the array and increment the count of each number modulo k
    for (int num : arr) {
        int mod = num % k;
        Integer count = map.get(mod);
        if (count == null) {
            count = 1;
        } else {
            count++;
        }
        map.put(mod, count);
    }

    // Iterate through the hash map and check if the count of each number is even
    for (int mod : map.keySet()) {
        if (map.get(mod) % 2 != 0) {
            return false;
        }
    }

    // All counts are even, return true
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0 || n < 2 || k < 2) {
        return false;
    }
    int[] counts = new int[k];
    for (int i = 0; i < n / 2; i++) {
        int a = arr[i];
        int b = arr[n - 1 - i];
        int sum = a + b;
        if (sum % k != 0) {
            return false;
        }
        counts[sum / k]++;
    }
    for (int i = 1; i < k; i++) {
        if (counts[i] % 2 != 0) {
            return false;
        }
    }
    return true;
}

