    int[] pairs = new int[n];
    for (int i = 0; i < n; i++) {
        pairs[i] = arr[i] + arr[n + i];
    }
    for (int i = 0; i < n; i++) {
        if (pairs[i] % k != 0) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int time = 0;
    int[] visited = new int[n];
    int[] dist = new int[n];
    Arrays.fill(visited, Integer.MAX_VALUE);
    Arrays.fill(dist, Integer.MAX_VALUE);

    dist[0] = 0;

    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1; j++) {
            if (visited[i] != Integer.MAX_VALUE && dist[i] != Integer.MAX_VALUE && dist[j] > dist[i] + 1) {
                dist[j] = dist[i] + 1;
            }
        }
        visited[i] = Integer.MAX_VALUE;
    }

    int count = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            time += dist[i];
            count++;
        }
    }

    time += count - 1;

    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a hash map to keep track of the nodes that have already been visited
    HashMap<Integer, Boolean> visited = new HashMap<>();
    for (int i = 0; i < n; i++) {
        visited.put(i, false);
    }

    // Initialize two queues to keep track of the nodes to visit and the time required to visit each node
    Queue<Integer> queue = new LinkedList<>();
    Queue<Integer> timeQueue = new LinkedList<>();

    // Add the starting node to the queue and set its time to 0
    queue.add(0);
    timeQueue.add(0);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        int node = queue.poll();
        int time = timeQueue.poll();

        // If the node has already been visited, skip it
        if (visited.get(node)) {
            continue;
        }

        // If the node has an apple, add the time required to visit it to the total time
        if (hasApple[node]) {
            time += 2;
        } else {
            // If the node does not have an apple, add its children to the queue
            for (int i = 0; i < edges[node].length; i++) {
                int child = edges[node][i];
                queue.add(child);
                timeQueue.add(time + 1);
            }
        }

        // Mark the node as visited and update the time required to visit it
        visited.put(node, true);
        visited.put(node, time);
    }

    // Return the minimum time required to visit all the nodes
    return visited.get(0);
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] distance = new int[n];
    Arrays.fill(distance, Integer.MAX_VALUE);

    // Initialize the distance array with distances from node 0
    for (int i = 0; i < edges.length; i++) {
        int from = edges[i][0];
        int to = edges[i][1];
        if (from == 0) {
            distance[to] = 1;
        } else if (to == 0) {
            distance[from] = 1;
        }
    }

    // Iterate over the edges and update the distance array
    for (int i = 0; i < edges.length; i++) {
        int from = edges[i][0];
        int to = edges[i][1];
        if (distance[from] != Integer.MAX_VALUE) {
            distance[to] = Math.min(distance[to], distance[from] + 1);
        }
    }

    // Calculate the total time required to collect all the apples
    int totalTime = 0;
    for (int i = 0; i < distance.length; i++) {
        if (distance[i] != Integer.MAX_VALUE && hasApple[i]) {
            totalTime += distance[i];
        }
    }

    // Add the time required to return to node 0
    totalTime += distance[0];

    return totalTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] distances = new int[n];
    Arrays.fill(distances, Integer.MAX_VALUE);
    distances[0] = 0;

    for (int i = 0; i < n; i++) {
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            if (distances[u] != Integer.MAX_VALUE && distances[v] > distances[u] + 1) {
                distances[v] = distances[u] + 1;
            }
        }
    }

    int totalTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            totalTime += distances[i];
        }
    }
    return totalTime;
}

