public String sortString(String s) {
    if (s == null || s.isEmpty()) return s;
    char[] charArray = s.toCharArray();
    Arrays.sort(charArray);
    StringBuilder result = new StringBuilder();
    while (result.length() < s.length()) {
        char minChar = charArray[0];
        for (int i = 1; i < charArray.length; i++) {
            if (charArray[i] < minChar) minChar = charArray[i];
        }
        result.append(minChar);
        for (int i = 0; i < charArray.length; i++) {
            if (charArray[i] == minChar && i != 0) {
                char temp = charArray[i];
                charArray[i] = charArray[i - 1];
                charArray[i - 1] = temp;
            }
        }
        char maxChar = charArray[charArray.length - 1];
        for (int i = charArray.length - 2; i >= 0; i--) {
            if (charArray[i] > maxChar) maxChar = charArray[i];
        }
        result.append(maxChar);
        for (int i = charArray.length - 1; i >= 0; i--) {
            if (charArray[i] == maxChar && i != charArray.length - 1) {
