      char largest = '\u0000';
      for (int i = s.length() - 1; i >= 0; i--) {
        if (s.charAt(i) > largest) {
          largest = s.charAt(i);
        }
      }
      result += largest;

      // Step 5: Pick the largest character from s which is smaller than the last appended character to the result and append it.
      while (result.length() < s.length() && s.lastIndexOf(largest) != -1) {
        largest = '\u0000';
        for (int i = s.length() - 1; i >= 0; i--) {
          if (s.charAt(i) == largest && s.charAt(i) < result.charAt(result.length() - 1)) {
            largest = s.charAt(i);
          }
        }
        if (largest != '\u0000') {
          result += largest;
        }
      }

      // Step 6: Repeat step 5 until you cannot pick more characters.
    }
    return result;
  }

