public String sortString(String s) {
    String result = "";
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    while (result.length() < s.length()) {
        // Step 1: Pick the smallest character
        int smallestIndex = 0;
        for (int i = 1; i < s.length(); i++) {
            if (chars[i] < chars[smallestIndex]) {
                smallestIndex = i;
            }
        }
        result += chars[smallestIndex];
        // Step 2: Pick the smallest character greater than the last appended character
        int smallestGreaterIndex = -1;
        for (int i = smallestIndex + 1; i < s.length(); i++) {
            if (chars[i] < result.charAt(result.length() - 1)) {
                smallestGreaterIndex = i;
                break;
            }
        }
        if (smallestGreaterIndex != -1) {
            result += chars[smallestGreaterIndex];
        }
        // Step 3: Pick the largest character
        int largestIndex = s.length() - 1;
        for (int i = s.length() - 2; i >= 0; i--) {
            if (chars[i] > chars[largestIndex]) {
                largestIndex = i;
            }
        }
        result += chars[largestIndex];
        // Step 4: Pick the largest character smaller than the last appended character
        int largestSmallerIndex = -1;
        for (int i = largestIndex - 1; i >= 0; i--) {
            if (chars[i] > result.charAt(result.length() - 1)) {
                largestSmallerIndex = i;
                break;
            }
        }
        if (largestSmallerIndex != -1) {
            result += chars[largestSmallerIndex];
        }
    }
    return result;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int average = sum / nums.length;
    int sum1 = 0;
    int sum2 = 0;
    int i = 0;
    while (i < nums.length) {
        if (i % 2 == 0) {
            sum1 += nums[i];
        } else {
            sum2 += nums[i];
        }
        i++;
    }
    return average == (sum1 + sum2) / 2;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) {
        return false;
    }
    int sum = 0;
    for (int i : nums) {
        sum += i;
    }
    int average = sum / n;
    int leftSum = 0;
    for (int i = 0; i < n / 2; i++) {
        leftSum += nums[i];
    }
    if (leftSum != average * (n / 2)) {
        return false;
    }
    int rightSum = 0;
    for (int i = n / 2; i < n; i++) {
        rightSum += nums[i];
    }
    return rightSum == average * (n - n / 2);
}

public boolean splitArraySameAverage(int[] nums) {
