    int count = 0;
    int sum = 0;
    for (int i = 0; i < nums.length; i++) {
        if (nums[i] % avg == 0) {
            count++;
            sum += nums[i];
        }
    }
    if (count == 0) {
        return false;
    }
    return sum / count == avg;
}

