public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(cost[i] + dp[i - 1], cost[i] + dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    // Initialize the minimum cost to reach the top as infinity
    int minCost = Integer.MAX_VALUE;
    // Initialize the current cost as 0
    int currentCost = 0;
    // Initialize the current index as 0
    int currentIndex = 0;

    // Loop through the costs and find the minimum cost to reach the top
    while (currentIndex < cost.length) {
        // Calculate the cost to climb two steps from the current index
        int twoStepCost = currentCost + cost[currentIndex];
        // Check if the cost to climb two steps is less than the current minimum cost
        if (twoStepCost < minCost) {
            // Update the minimum cost and current cost
            minCost = twoStepCost;
            currentCost = twoStepCost;
            // Increment the current index by two
            currentIndex += 2;
        } else {
            // Calculate the cost to climb one step from the current index
            int oneStepCost = currentCost + cost[currentIndex];
            // Check if the cost to climb one step is less than the current minimum cost
            if (oneStepCost < minCost) {
                // Update the minimum cost and current cost
                minCost = oneStepCost;
                currentCost = oneStepCost;
                // Increment the current index by one
                currentIndex += 1;
            } else {
                // Break the loop if the cost to climb two steps is greater than or equal to the current minimum cost
                break;
            }
        }
    }

    // Return the minimum cost to reach the top
    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    int minCost = 0;
    int minCost0 = cost[0];
    int minCost1 = cost[1];

    for (int i = 2; i < cost.length; i++) {
      minCost = Math.min(minCost0 + cost[i], minCost1 + cost[i - 1]);
      minCost0 = minCost1;
      minCost1 = minCost;
    }

    return Math.min(minCost0, minCost1);
  }

public int minCostClimbingStairs(int[] cost) {
    if (cost.length == 1) return cost[0];
    if (cost.length == 2) return Math.min(cost[0], cost[1]);

    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < cost.length; i++) {
        dp[i] = Math.min(dp[i-1] + cost[i], dp[i-2] + cost[i-1]);
    }

    return Math.min(dp[cost.length-1], dp[cost.length-2]);
}

