public boolean hasAllCodes(String s, int k) {
    // Check if the input parameters are valid
    if (k <= 0 || s == null || s.length() == 0) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    // Initialize a set to store all the substrings of length k
    Set<String> substrings = new HashSet<>();

    // Iterate through the string and add all substrings of length k to the set
    for (int i = 0; i < s.length() - k + 1; i++) {
        substrings.add(s.substring(i, i + k));
    }

    // Check if all the possible substrings of length k are present in the set
    for (int i = 0; i < (1 << k); i++) {
        String substring = Integer.toBinaryString(i).substring(0, k);
        if (!substrings.contains(substring)) {
            return false;
        }
    }

    // If all substrings are present, return true
    return true;
}

public boolean hasAllCodes(String s, int k) {
    // Check if k is a valid boundary for the input string s
    if (k <= 0 || k > s.length()) {
        return false;
    }

    // Loop through each substring of length k in the input string
    for (int i = 0; i <= s.length() - k; i++) {
        // Check if the substring is not a valid binary string
        if (!isValidBinary(s.substring(i, i + k))) {
            return false;
        }
    }

    // If all substrings are valid binary strings, return true
    return true;
}

