public int minInsertions(String s) {
    int[] insertionCounts = new int[s.length()];
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == ')' && s.charAt(i - 1) == '(') {
            insertionCounts[i] = Math.min(insertionCounts[i - 1] + 1, 1);
        } else if (s.charAt(i) == ')') {
            insertionCounts[i] = Math.min(insertionCounts[i] + 1, 1);
        } else if (s.charAt(i) == '(') {
            insertionCounts[i] = Math.min(insertionCounts[i] + 1, 0);
        }
    }
    return Math.min(insertionCounts[s.length() - 1], 1);
}

public int minInsertions(String s) {
    int minInsertions = 0;
    Stack<Character> stack = new Stack<>();
    for (char c : s.toCharArray()) {
        if (c == '(') {
            stack.push(c);
        } else {
            if (stack.isEmpty() || stack.peek() != '(') {
                minInsertions++;
            } else {
                stack.pop();
            }
        }
    }
    while (!stack.isEmpty()) {
        minInsertions++;
        stack.pop();
    }
    return minInsertions;
}

