public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int minOperations = 0;
    while (!allElementsEqual(arr)) {
        int minDiff = findMinDiffIndex(arr, n);
        int x = minDiff / 2;
        int y = minDiff % 2;
        arr[x]--;
        arr[y]++;
        minOperations++;
    }
    return minOperations;
}

private boolean allElementsEqual(int[] arr) {
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] != arr[0]) {
            return false;
        }
    }
    return true;
}

private int findMinDiffIndex(int[] arr, int n) {
    int minDiff = Integer.MAX_VALUE;
    int minDiffIndex = -1;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int diff = Math.abs(arr[i] - arr[j]);
            if (diff < minDiff) {
                minDiff = diff;
                minDiffIndex = j;
            }
        }
    }
    return minDiffIndex;
}

public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int oper = 0;
    while (arr[0] != arr[n - 1]) {
        int maxIndex = findMaxIndex(arr);
        int minIndex = findMinIndex(arr);
        arr[maxIndex] -= 1;
        arr[minIndex] += 1;
        oper++;
    }
    return oper;
}

private int findMaxIndex(int[] arr) {
    int maxIndex = 0;
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] > arr[maxIndex]) {
            maxIndex = i;
        }
    }
    return maxIndex;
}

private int findMinIndex(int[] arr) {
    int minIndex = 0;
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] < arr[minIndex]) {
            minIndex = i;
        }
