Public String getSmallestString(int n, int k) {
    String smallest = "";
    for (int i = 0; i < n; i++) {
        smallest += (char) (k % 26 + 'a');
        k /= 26;
    }
    return smallest;
}

Explanation:
This method generates the lexicographically smallest string by appending characters to the end of the string character-by-character. The value of a character is determined by its position in the alphabet (starting from 1), so we can use the modulo operation to get the value of the current character and divide the input value by 26 to get the value of the next character. We stop when we reach the desired length of the string.
This method works because the lexicographically smallest string is the one that starts with the letter 'a' and the characters that follow are the next letters in the alphabet, in order. By incrementing the value by 1 when we append a new character to the string, we can ensure that the string starts with the letter 'a' and continues with the next letters in the alphabet, ending at the correct length.

public String getSmallestString(int n, int k) {
    if (n <= 0 || k <= 0) {
        throw new IllegalArgumentException("Invalid input");
    }

    StringBuilder res = new StringBuilder();
    while (n > 0) {
        res.append((char) ('a' + (k - 1) % 26));
        n--;
        k = (k - 1) / 26;
    }
    return res.reverse().toString();
}

public String getSmallestString(int n, int k) {
    //Check if the input is valid
    if(n < 1 || k < 1) {
        throw new IllegalArgumentException("n and k must be positive integers");
    }

    //Initialize the string with the first character
    String smallest = String.valueOf((char)('a' + (k - 1)));

    //Loop through the remaining characters
    for(int i = 1; i < n - 1; i++) {
        //Check if the next character is valid
        if(k >= 26) {
            //If not, roll over to the next letter
            smallest = smallest.concat(String.valueOf('a'));
            k = k - 26;
        } else {
            //If yes, append the next character to the string
            smallest = smallest.concat(String.valueOf((char)('a' + k)));
            k = 0;
        }
    }

    //Return the final string
    return smallest;
}

public String getSmallestString(int n, int k) {
    String result = "";
    int[] positions = new int[26];

    // Initialize the positions of the characters in the alphabet
    for (int i = 0; i < 26; i++) {
        positions[i] = i + 1;
    }

    // Loop through each character in the result string
    for (int i = 0; i < n; i++) {
        // Find the smallest position that is less than or equal to k
        int minPosition = -1;
        for (int j = 0; j < 26; j++) {
            if (positions[j] <= k) {
                minPosition = j;
                break;
            }
        }

        // Add the character to the result string
        result += (char) (minPosition + 'a');

        // Subtract the position of the character from k
        k -= positions[minPosition];
    }

    return result;
}

