                // check vertical line
                for (int k = i; k < mat.length && mat[k][j] == 1; k++) {
                    lineLength++;
                }
                // check diagonal line
                for (int k = 1; i + k < mat.length && j + k < mat[i].length && mat[i + k][j + k] == 1; k++) {
                    lineLength++;
                }
                // check anti-diagonal line
                for (int k = 1; i - k >= 0 && j + k < mat[i].length && mat[i - k][j + k] == 1; k++) {
                    lineLength++;
                }
                if (lineLength > longestLine) {
                    longestLine = lineLength;
                }
            }
        }
    }
    return longestLine;
}

