    }
    int count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            int k = squareRoot(sum[j] - sum[i]);
            if (k > 0 && k * k == sum[j] - sum[i]) {
                count++;
            }
        }
    }
    return count;
}

