    int root = (int) Math.sqrt(x);
    return root * root == x ? root : -1;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    int[] permutations = new int[n];
    int numSquarePermutations = 0;

    for (int i = 0; i < n; i++) {
        permutations[i] = A[i];
    }

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int sum = permutations[i] + permutations[j];
            if (isPerfectSquare(sum)) {
                swap(permutations, i, j);
                numSquarePermutations++;
            }
        }
    }

    // Check for duplicates
    for (int i = 0; i < numSquarePermutations; i++) {
        for (int j = i + 1; j < numSquarePermutations; j++) {
            if (permutations[i] == permutations[j]) {
                numSquarePermutations--;
            }
        }
    }

    return numSquarePermutations;
}

