            while (nextIndex != i) {
                boolean isSquare = isSquare(sum + A[nextIndex]);
                visited[nextIndex] = true;
                nextIndex = (nextIndex + 1) % n;
                if (isSquare) {
                    count++;
                }
            }
        }
    }
    return count;
}

