    Arrays.fill(right, n - 1);

    int maxArea = 0;
    for (int i = 1; i < n; i++) {
        int height = heights[i];
        int position = i - 1;
        while (position >= 0 && heights[position] >= height) {
            position = left[position];
        }
        left[i] = position;
    }

