        for (int i = 0; i < 10; i++) {
            num += digits[i] * Math.pow(10, i);
        }
        if (num > smallest && num > n) {
            smallest = num;
        }
    } while (next_permutation(digits));

    return smallest;
}

static boolean next_permutation(int[] arr) {
    int i = arr.length - 2;
    while (i >= 0 && arr[i] >= arr[i + 1]) {
        i--;
    }
    if (i == -1) {
        return false;
    }
    int j = arr.length - 1;
    while (arr[j] <= arr[i]) {
        j--;
    }
    swap(arr, i, j);
    j = arr.length - 1;
    while (i < j) {
        swap(arr, i, j);
        i++;
        j--;
    }
    return true;
}

static void swap(int[] arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

