private static boolean isCenterSymmetric(String number) {
    if (number.length() == 1) {
        return true;
    }

    int left = 0;
    int right = number.length() - 1;

    while (left < right) {
        if (number.charAt(left) != number.charAt(right)) {
            return false;
        }
        left++;
        right--;
    }

    return true;
}

