private static boolean isCenterSymmetricNumber(String numStr) {
    // Check if the number is of even length
    if (numStr.length() % 2 != 0) {
        return false;
    }

    // Check if the first half and last half of the number are the same
    int mid = numStr.length() / 2;
    String firstHalf = numStr.substring(0, mid);
    String lastHalf = numStr.substring(mid);
    return firstHalf.equals(lastHalf);
}

