public static int calculateEnergy(String s) {
    int energy = 1;
    char currentChar = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == currentChar) {
            energy++;
        } else {
            if (energy > 1) {
                return energy;
            }
            energy = 1;
            currentChar = c;
        }
    }
    return energy;
}

public static int calculateEnergy(String s) {
    int energy = 0;
    // if the input string is empty, return 0
    if (s.isEmpty()) {
        return energy;
    }
    // iterate through the string and find the longest non-empty substring containing only one character
    for (int i = 0; i < s.length(); i++) {
        char currChar = s.charAt(i);
        int length = 0;
        while (i + length < s.length() && s.charAt(i + length) == currChar) {
            length++;
        }
        // update the energy if the current substring is longer than previous ones
        if (length > energy) {
            energy = length;
        }
    }
    return energy;
}

